using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {
 public static class ReferenceDesignTests {
  static int checks;static void Check(bool v,string text){checks++;if(!v)throw new Exception(text);}static void Near(double a,double b,string text){Check(Math.Abs(a-b)<1e-6,text);}
  static void Wait(Func<bool> f,string text){var timer=System.Diagnostics.Stopwatch.StartNew();while(!f()&&timer.Elapsed.TotalSeconds<120){Application.DoEvents();Thread.Sleep(20);}Check(f(),text);}
  static T Get<T>(Task<T> task){Wait(()=>task.IsCompleted,"viewport response");return task.GetAwaiter().GetResult();}
  static void Shot(RobotDesignerForm robot,string path){var until=DateTime.UtcNow.AddMilliseconds(450);Wait(()=>DateTime.UtcNow>until,"render settled");var task=robot.WebScene.SavePreview(path);Wait(()=>task.IsCompleted,"native screenshot");task.GetAwaiter().GetResult();}
  static void Call(object obj,string method){obj.GetType().GetMethod(method,System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(obj,new object[0]);}
  public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};var d=RobotDocument.CassetteReference();Check(d.Joints.Count==6&&d.Joints.All(j=>j.BodyGenerator!=null&&j.BodyGenerator.ReferenceDesign),"new example selects actual reference topology");Check(d.ReferenceGripper,"reference includes two-jaw tool");Near(d.Joints[0].Length,110,"reference base proportion");Near(d.Joints[3].Length,100,"reference wrist proportion");Near(new ProceduralBodySettings().InsertLength,5.2,"mechanical default preserved across version change");Check(!new ProceduralBodySettings().ReferenceDesign,"old projects retain previous topology by default");
   foreach(var j in d.Joints){Check(j.GeneratedBody!=null&&j.GeneratedBody.Result.GeometryValid,"native baked geometry "+j.Name);Check(j.GeneratedBody.Fingerprint==ProceduralBodySpec.Fingerprint(d,j,j.BodyGenerator),"baked cache current "+j.Name);if(d.Joints.Any(c=>c.ParentId==j.Id)){Check(j.GeneratedBody.Result.Modules["design"]=="reference-cassette","distinct native topology "+j.Name);Check(j.GeneratedBody.Result.Parts.Any(p=>p.Label.Contains("утопленная")),"separate inset cover "+j.Name);}}
   var model=RobotCad.Build(d);Check(model.Model.Valid,"reference complete build");var terminal=d.Ordered().Last();var tool=model.Entries[terminal.Id+"_tool_adapter"];var port=terminal.GeneratedBody.Result.Mates.Single(m=>m.Id=="tool_mount");Check(tool.Shape.Holes.Count==port.BoltPoints.Length,"actual adapter bolt pattern");var matrix=tool.Local*d.Joints.Last().GeneratedBody.Result.Parts.Where(p=>p.Id=="frame_0").Select(p=>model.Current[terminal.Id].Output).First();var flange=RobotMath.Frame(terminal.Axis)*model.Current[terminal.Id].Output;foreach(var p in tool.Shape.Holes){var point=matrix.Transform(new Point3D(p.X,p.Y,0));Check(port.BoltPoints.Select(q=>(flange.Transform(new Point3D(q[0],q[1],q[2]))-point).Length).Min()<1e-5,"tool bores coincide in world frame");}
   var zero=d.Clone();foreach(var item in zero.Joints)item.Position=0;var weightless=RobotCad.Build(zero);foreach(var item in weightless.Entries.Values)item.MassOverride=0;Near(RobotSolver.Solve(weightless).Joints[1].Required,.5*9.81*.139*1.5,"payload acts at finger TCP, not wrist origin");var last=zero.Ordered().Last();var actual=weightless.Pose(last.Id+"_tool_adapter",0,false).Transform(new Point3D(0,0,64));Check((actual-RobotSolver.LoadPoint(zero,last,weightless.Current)).Length<1e-5,"load point equals actual CAD fingertip");
   string original=d.Serialize();var roundtrip=RobotDocument.Parse(original);Check(roundtrip.ReferenceGripper&&roundtrip.Joints.All(j=>j.BodyGenerator.ReferenceDesign),"design flags persisted");roundtrip.Save(Path.Combine(folder,"Reference.robot.json"));
   using(var robot=new RobotDesignerForm())using(var shell=new WorkspaceShell(robot)){robot.SetDocument(d);shell.Show();Wait(()=>robot.WebScene.Ready&&robot.Scene.Ready,"actual reference scene");int count=robot.Build.Entries.Values.Count(e=>!e.Guide);Wait(()=>{string json=CADDocument.Serializer().Deserialize<string>(Get(robot.WebScene.Inspect()));var info=CADDocument.Serializer().DeserializeObject(json) as Dictionary<string,object>;return Convert.ToInt32(info["parts"])==count&&Convert.ToInt32(info["triangles"])>1000;},"all actual meshes present");robot.SetStage(2);robot.WebScene.Send(new{type="preset",view="REFERENCE"});robot.WebScene.Send(new{type="presentation",enabled=true});Shot(robot,Path.Combine(folder,"reference-studio.png"));
    var keys=robot.Document.Joints.Select(j=>j.GeneratedBody.Fingerprint).ToArray();Call(robot,"ToggleGripperOpening");Near(robot.Document.GripperOpening,2,"gripper closes");var left=robot.Build.Entries[terminal.Id+"_tool_jaw_-1"];var right=robot.Build.Entries[terminal.Id+"_tool_jaw_1"];Near(right.Shape.X-left.Shape.X,6,"jaw separation follows opening");Check(robot.Document.Joints.Select(j=>ProceduralBodySpec.Fingerprint(robot.Document,j,j.BodyGenerator)).SequenceEqual(keys),"jaw opening retains native bodies");Check(robot.Build.Model.Valid,"gripper update remains a valid assembly");
    Wait(()=>robot.Scene.Ready,"gripper mesh update settled");robot.ResetJointPose();robot.WebScene.Send(new{type="preset",view="YZ"});Shot(robot,Path.Combine(folder,"reference-straight-side.png"));robot.WebScene.Send(new{type="preset",view="XZ"});Shot(robot,Path.Combine(folder,"reference-straight-front.png"));
    robot.SetDocument(RobotDocument.Parse(original));robot.OpenJointControllers();Wait(()=>robot.Scene.Ready,"restored native scene ready");robot.WebScene.Send(new{type="preset",view="REFERENCE"});robot.WebScene.Send(new{type="presentation",enabled=true});Shot(robot,Path.Combine(folder,"reference-controls.png"));
    var legacy=RobotDocument.Example();var dimensions=legacy.Joints.Select(j=>j.Length).ToArray();robot.SetDocument(legacy);robot.ApplyReferenceDesign();Check(robot.Document.Joints.All(j=>j.BodyGenerator.ReferenceDesign),"explicit conversion applies reference design");Check(robot.Document.Joints.Select(j=>j.Length).SequenceEqual(dimensions),"conversion preserves custom skeleton lengths");Call(robot,"Undo");Check(robot.Document.Joints.All(j=>j.BodyGenerator==null||!j.BodyGenerator.ReferenceDesign),"one undo restores original design");
    shell.ApproveTestClose();shell.Close();
   }
   File.WriteAllText(Path.Combine(folder,"reference-results.txt"),"PASS "+checks+" reference-design assertions: distinct CAD topology, inset covers, matching tool mount, persistence, live jaw opening, studio/native views, custom skeleton preservation and undo.\r\n",Encoding.UTF8);return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(folder,"reference-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=old;}}
 }
}
